const TokenError$arm$InvalidRequest = memo(() => type({ "+": "reject", InvalidRequest: "null" }));
const TokenError$arm$InvalidGrant = memo(() => type({ "+": "reject", InvalidGrant: "null" }));
export const TokenError: Wire<TokenError$> = type("unknown").pipe((v, ctx): TokenError$ => {
  if (v === "InvalidRequest") return { kind: "InvalidRequest" };
  {
    const parsed = TokenError$arm$InvalidRequest()(v);
    if (!(parsed instanceof type.errors)) return { kind: "InvalidRequest" };
    if (keyed(v, "InvalidRequest")) return fail(ctx, parsed);
  }
  if (v === "InvalidGrant") return { kind: "InvalidGrant" };
  {
    const parsed = TokenError$arm$InvalidGrant()(v);
    if (!(parsed instanceof type.errors)) return { kind: "InvalidGrant" };
    if (keyed(v, "InvalidGrant")) return fail(ctx, parsed);
  }
  return ctx.error("TokenError") as never;
});

/** Each type written as serde_json writes the Rust value. */
export const toJson = {
  ErrorCode: (x: ErrorCode$): string => `"${x.kind}"`,
  DisplayError: (x: DisplayError$): string => `"${x.kind}"`,
  ErrorRedirect: (x: ErrorRedirect$): string => `{"redirect_uri":${Json.str(x.redirect_uri)},"error":${toJson.ErrorCode(x.error)},"state":${(x.state === null ? "null" : Json.str(x.state))}}`,
  AuthorizationError: (x: AuthorizationError$): string => {
    switch (x.kind) {
      case "Display":
        return `{"Display":${toJson.DisplayError(x.content[0])}}`;
      case "Redirect":
        return `{"Redirect":${toJson.ErrorRedirect(x.content[0])}}`;
    }
  },
  Client: (x: Client$): string => `{"client_id":${Json.str(x.client_id)},"redirect_uris":${Json.array(x.redirect_uris, (v0) => Json.str(v0))},"require_pkce":${Json.bool(x.require_pkce)},"allow_plain_pkce":${Json.bool(x.allow_plain_pkce)}}`,
  AuthorizationParams: (x: AuthorizationParams$): string => `{"client_id":${(x.client_id === null ? "null" : Json.str(x.client_id))},"response_type":${(x.response_type === null ? "null" : Json.str(x.response_type))},"redirect_uri":${(x.redirect_uri === null ? "null" : Json.str(x.redirect_uri))},"scope":${(x.scope === null ? "null" : Json.str(x.scope))},"state":${(x.state === null ? "null" : Json.str(x.state))},"nonce":${(x.nonce === null ? "null" : Json.str(x.nonce))},"code_challenge":${(x.code_challenge === null ? "null" : Json.str(x.code_challenge))},"code_challenge_method":${(x.code_challenge_method === null ? "null" : Json.str(x.code_challenge_method))},"prompt":${(x.prompt === null ? "null" : Json.str(x.prompt))},"max_age":${(x.max_age === null ? "null" : Json.str(x.max_age))},"acr_values":${(x.acr_values === null ? "null" : Json.str(x.acr_values))}}`,
  AuthStrength: (x: AuthStrength$): string => `"${x.kind}"`,
  Session: (x: Session$): string => `{"subject":${Json.str(x.subject)},"auth_time":${Json.int(x.auth_time)},"strength":${toJson.AuthStrength(x.strength)}}`,
  Policy: (x: Policy$): string => `{"max_password_failures":${Json.int(x.max_password_failures)},"max_otp_failures":${Json.int(x.max_otp_failures)}}`,
  PkceMethod: (x: PkceMethod$): string => `"${x.kind}"`,
  Pkce: (x: Pkce$): string => `{"challenge":${Json.str(x.challenge)},"method":${toJson.PkceMethod(x.method)}}`,
  Prompt: (x: Prompt$): string => `{"no_interaction":${Json.bool(x.no_interaction)},"login":${Json.bool(x.login)},"consent":${Json.bool(x.consent)},"select_account":${Json.bool(x.select_account)}}`,
  AuthorizationRequest: (x: AuthorizationRequest$): string => `{"client_id":${Json.str(x.client_id)},"redirect_uri":${Json.str(x.redirect_uri)},"scope":${Json.str(x.scope)},"state":${Json.str(x.state)},"nonce":${(x.nonce === null ? "null" : Json.str(x.nonce))},"pkce":${(x.pkce === null ? "null" : toJson.Pkce(x.pkce))},"prompt":${toJson.Prompt(x.prompt)},"max_age":${(x.max_age === null ? "null" : Json.int(x.max_age))},"wants_mfa":${Json.bool(x.wants_mfa)}}`,
  OtpDigits: (x: OtpDigits$): string => `"${x.kind}"`,
  TotpEnrollment: (x: TotpEnrollment$): string => `{"t0":${Json.int(x.t0)},"period":${Json.int(x.period)},"digits":${toJson.OtpDigits(x.digits)},"last_used_step":${(x.last_used_step === null ? "null" : Json.int(x.last_used_step))}}`,
  StepMac: (x: StepMac$): string => `{"step":${Json.int(x.step)},"mac":${Json.array(x.mac, (v0) => Json.int(v0))}}`,
  OtpCheck: (x: OtpCheck$): string => {
    switch (x.kind) {
      case "Accepted":
        return `{"Accepted":${Json.int(x.content[0])}}`;
      case "Replayed":
        return "\"Replayed\"";
      case "Mismatch":
        return "\"Mismatch\"";
      case "Malformed":
        return "\"Malformed\"";
      case "ClockBeforeEpoch":
        return "\"ClockBeforeEpoch\"";
    }
  },
  Notice: (x: Notice$): string => `"${x.kind}"`,
  Authentication: (x: Authentication$): string => `{"subject":${Json.str(x.subject)},"auth_time":${Json.int(x.auth_time)},"strength":${toJson.AuthStrength(x.strength)},"totp_step":${(x.totp_step === null ? "null" : Json.int(x.totp_step))}}`,
  CodeGrant: (x: CodeGrant$): string => `{"client_id":${Json.str(x.client_id)},"redirect_uri":${Json.str(x.redirect_uri)},"scope":${Json.str(x.scope)},"state":${Json.str(x.state)},"nonce":${(x.nonce === null ? "null" : Json.str(x.nonce))},"pkce":${(x.pkce === null ? "null" : toJson.Pkce(x.pkce))},"subject":${Json.str(x.subject)},"auth_time":${Json.int(x.auth_time)},"amr":${Json.array(x.amr, (v0) => Json.str(v0))},"acr":${Json.str(x.acr)}}`,
  Flow: (x: Flow$): string => {
    switch (x.kind) {
      case "AwaitingPassword":
        return `{"AwaitingPassword":{"request":${toJson.AuthorizationRequest(x.request)},"failures":${Json.int(x.failures)},"notice":${toJson.Notice(x.notice)}}}`;
      case "AwaitingOtp":
        return `{"AwaitingOtp":{"request":${toJson.AuthorizationRequest(x.request)},"subject":${Json.str(x.subject)},"enrollment":${toJson.TotpEnrollment(x.enrollment)},"failures":${Json.int(x.failures)},"notice":${toJson.Notice(x.notice)}}}`;
      case "AwaitingConsent":
        return `{"AwaitingConsent":{"request":${toJson.AuthorizationRequest(x.request)},"auth":${toJson.Authentication(x.auth)}}}`;
      case "CodeIssued":
        return `{"CodeIssued":${toJson.CodeGrant(x.content[0])}}`;
      case "Rejected":
        return `{"Rejected":${toJson.ErrorRedirect(x.content[0])}}`;
      case "Locked":
        return "\"Locked\"";
    }
  },
  SecondFactor: (x: SecondFactor$): string => {
    switch (x.kind) {
      case "Totp":
        return `{"Totp":${toJson.TotpEnrollment(x.content[0])}}`;
      case "NotEnrolled":
        return "\"NotEnrolled\"";
    }
  },
  Event: (x: Event$): string => {
    switch (x.kind) {
      case "PasswordChecked":
        return `{"PasswordChecked":{"subject":${Json.str(x.subject)},"verified":${Json.bool(x.verified)},"second_factor":${toJson.SecondFactor(x.second_factor)},"now":${Json.int(x.now)}}}`;
      case "OtpSubmitted":
        return `{"OtpSubmitted":{"code":${Json.str(x.code)},"now":${Json.int(x.now)},"candidates":${Json.array(x.candidates, (v0) => toJson.StepMac(v0))}}}`;
      case "ConsentGranted":
        return "\"ConsentGranted\"";
      case "ConsentDenied":
        return "\"ConsentDenied\"";
    }
  },
  FlowError: (x: FlowError$): string => `"${x.kind}"`,
  TokenError: (x: TokenError$): string => `"${x.kind}"`,
} as const;
